"""Split a line into pieces and parse the strings."""
def split_line(line: Any, parsers: Any, sep: Any = " ") -> object {
    parts = [
        part
        for part in line.split(sep)
        if part
    ];
    values = [parser(part) for (parser, part) in zip(parsers, parts)];
    return values if (len(values) > 1) else values[0];
}

""" Utility method for parsing JIRA comments represented as JSON
        Args:
            comments: A variable containing JIRA comments in JSON
                      representation.
        Returns:
            A string containing all of the JIRA comments tied to an issue
    """
def extract_comments(comments: Any) -> object {
    size = len(comments);
    addtional_notes = "";
    for n in range(0, size) {
        addtional_notes = addtional_notes + comments[n]['body'] + "\n";
    }
    return addtional_notes;
}

