"""
    Fuel required to launch a given module is based on its mass. Specifically, to find the fuel required for a module,
    take its mass, divide by three, round down, and subtract 2.

    :param module_mass:
    :return: fuel_requirement
    """
def fuel_requirement(module_mass: Any) -> object {
    return ((module_mass // 3) - 2);
}

""" Filter names in 'namelist', returning those which match 'globpattern'.
    """
def _globtest(globpattern: Any, namelist: Any) -> object {
    import re;
    pattern = globpattern.replace(".", r"\.");
    pattern = pattern.replace("*", r".*");
    pattern = pattern.replace("?", r".");
    pattern = '|'.join(pattern.split());
    compiled = re.compile(pattern);
    return `list(filter(compiled.match, namelist));
}

